"""Balanced bracket checking with double-quoted string support."""


def balanced(s):
    """Return True when all brackets in s are matched and correctly ordered.

    Brackets inside double-quoted strings are ignored. Within a string a
    backslash escapes the next character. An unterminated string makes the
    input unbalanced.
    """
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    in_string = False
    escaped = False

    for ch in s:
        if in_string:
            if escaped:
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == '"':
                in_string = False
            continue

        if ch == '"':
            in_string = True
        elif ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack.pop() != pairs[ch]:
                return False

    return not stack and not in_string
